using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);

// Register ProblemDetails services so all error responses use RFC 7807 format.
builder.Services.AddProblemDetails();

// Register the custom exception handler.
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

var app = builder.Build();

// UseExceptionHandler invokes our IExceptionHandler for any unhandled exception,
// then falls back to ProblemDetailsService for the response body.
app.UseExceptionHandler();

app.UseHttpsRedirection();

// --- Demo endpoints ---

app.MapGet("/weatherforecast", () =>
{
    var summaries = new[]
    {
        "Freezing", "Bracing", "Chilly", "Cool", "Mild", "Warm", "Balmy", "Hot", "Sweltering", "Scorching"
    };

    var forecast = Enumerable.Range(1, 5).Select(index =>
        new WeatherForecast(
            DateOnly.FromDateTime(DateTime.Now.AddDays(index)),
            Random.Shared.Next(-20, 55),
            summaries[Random.Shared.Next(summaries.Length)]
        )).ToArray();

    return forecast;
});

// Endpoints that throw — handled globally, no try-catch needed.
app.MapGet("/demo/not-found", () =>
{
    throw new KeyNotFoundException("Item with ID 42 was not found.");
});

app.MapGet("/demo/bad-request", () =>
{
    throw new ArgumentException("Parameter 'email' is not a valid email address.");
});

app.MapGet("/demo/conflict", () =>
{
    throw new InvalidOperationException("Cannot delete a user who has active orders.");
});

app.MapGet("/demo/server-error", () =>
{
    throw new Exception("Something secret blew up — this message must NOT leak.");
});

app.Run();

// --- Types ---

record WeatherForecast(DateOnly Date, int TemperatureC, string? Summary)
{
    public int TemperatureF => 32 + (int)(TemperatureC / 0.5556);
}

/// <summary>
/// Maps well-known exception types to HTTP status codes and writes
/// RFC 7807 Problem Details responses via ProblemDetailsService.
/// </summary>
sealed class GlobalExceptionHandler(ILogger<GlobalExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext httpContext,
        Exception exception,
        CancellationToken cancellationToken)
    {
        var (statusCode, title) = exception switch
        {
            KeyNotFoundException     => (StatusCodes.Status404NotFound,  "Not Found"),
            ArgumentException        => (StatusCodes.Status400BadRequest, "Bad Request"),
            InvalidOperationException => (StatusCodes.Status409Conflict,  "Conflict"),
            _ => (StatusCodes.Status500InternalServerError, "Internal Server Error"),
        };

        logger.LogError(exception, "Unhandled exception ({ExceptionType})", exception.GetType().Name);

        httpContext.Response.StatusCode = statusCode;

        var problemDetails = new ProblemDetails
        {
            Status = statusCode,
            Title  = title,
            // Only surface the exception message for client errors; suppress for 500s.
            Detail = statusCode < 500 ? exception.Message : "An unexpected error occurred.",
            Instance = httpContext.Request.Path,
        };

        return await httpContext.RequestServices
            .GetRequiredService<IProblemDetailsService>()
            .TryWriteAsync(new ProblemDetailsContext
            {
                HttpContext    = httpContext,
                ProblemDetails = problemDetails,
            });
    }
}

